def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    blocks = []

    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2
                   for rr in (r, r + 1) for cc in (c, c + 1)):
                blocks.append((r, c))
                for rr in (r, r + 1):
                    for cc in (c, c + 1):
                        out[rr][cc] = 2

    # Marker locations around each block: TL, TR, BL, BR.
    offsets = [(-1, -1), (-1, 2), (2, -1), (2, 2)]
    # Each location receives the color from the preceding corner.
    source_for_dest = [2, 0, 3, 1]
    directions = [(-1, -1), (-1, 1), (1, -1), (1, 1)]

    for r, c in blocks:
        positions = [(r + dr, c + dc) for dr, dc in offsets]
        colors = [grid[rr][cc] if 0 <= rr < h and 0 <= cc < w else 0
                  for rr, cc in positions]

        for i, ((rr, cc), (step_r, step_c)) in enumerate(zip(positions, directions)):
            color = colors[source_for_dest[i]]
            if color == 0:
                continue
            while 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
                rr += step_r
                cc += step_c

    return out
